import { useAuth } from "../../contexts/AuthContext";
import { useNavigate } from "react-router-dom";
import { loginAdmin } from "../../services/admin/loginAdmin";

export default function Login() {
    const navigate = useNavigate();
    const { onLoginAdmin } = useAuth();

    const loginHandler = async (e) => {
        e.preventDefault();

        const formData = new FormData(e.currentTarget);
        const { username, password } = Object.fromEntries(formData);

        try {
            const adminResult = await loginAdmin(username, password);

            // Обработка на различните статус кодове
            if (adminResult.status === 400) {
                alert("Admin does not exist!");
                return;
            }

            if (adminResult.status === 401) {
                alert("Incorrect password!");
                return;
            }

            if (!adminResult.ok) {
                throw new Error("An unexpected error occurred!");
            }

            const data = await adminResult.json();
            onLoginAdmin(data);
            navigate("/admin/");

        } catch (error) {
            console.error("Login failed:", error);
            alert("Failed to log in. Please try again later.");
        }
    };

    return (
        <section id="admin">
            <div className="content">
                <h2>Admin Login</h2>
                <form onSubmit={loginHandler}>
                    <div className="form-group">
                        <label htmlFor="username">Username:</label>
                        <input
                            type="text"
                            id="username"
                            name="username"
                            placeholder="Enter your username"
                            required
                        />
                    </div>

                    <div className="form-group">
                        <label htmlFor="password">Password:</label>
                        <input
                            type="password"
                            id="password"
                            name="password"
                            placeholder="Enter your password"
                            required
                        />
                    </div>

                    <button type="submit" className="btn btn-primary">
                        Login
                    </button>
                </form>
            </div>
        </section>
    );
}
